internal sealed class StateApproximationS3QuantumAlgebraStateApproximationUniformSignedSquareDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Uniform signed squares in the original algebra", H("Uniform signed squares in the original algebra"), Blocks(
        Paragraph(Text("Let A be an arbitrary nontrivial C*-algebra in Type u with PartialOrder A and StarOrderedRing A. Let beta be a real linear positive normalized functional on selfAdjoint A, extreme in the whole original real state space. For every original self-adjoint k with beta(k) nonzero, one finite nonnegative L is chosen before every positive eta. There is an original self-adjoint e of norm at most L. Define square(e) as the self-adjoint subtype of e squared, sigma(r)=1 for positive r and minus one otherwise, and c=sigma(beta(k)) times square(e). The element c is self-adjoint, sigma(beta(k)) times c is nonnegative in A, its original norm is at most L squared, and sqrt(beta(square(c-k))) is less than eta. Both signs are included. There is no finite-dimensional, sequential or separability restriction. This assertion concerns C*-algebras; general JB algebras and the further Jordan-algebra conclusion are separate questions. The construction first forms a positive rank-one operator from pi(k)Omega, then its self-adjoint square root T. The bound L=1+norm(T) precedes the accuracy. Strong self-adjoint density and the original-A truncation e=L times cfc(f,a), f(t)=2t/(1+t squared), give the original norm bound and simultaneous approximation on Omega and T(Omega). Contractivity controls the squared actions. The exact GNS moment identity identifies the original beta square reading with the represented vector norm.")),
        Describe.Lean(DescribeId.Create("statement0"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.sigma_sq"),
            H("sigma_sq"), StatementSource.FromAuthor(Disp(Statement0())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("By the definition of sigma, its value is 1 when r is positive and -1 otherwise. In either branch multiplying it by itself gives 1. The nonpositive branch includes r=0, so no nonzero hypothesis is needed for this identity."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement1"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.sigma_abs"),
            H("sigma_abs"), StatementSource.FromAuthor(Disp(Statement1())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Unfold sigma and split on positivity of r. Both possible values, 1 and -1, have absolute value 1, including the convention at zero. This identity will remove the sign from norm estimates."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement2"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.signedSquare_cone"),
            H("signedSquare_cone"), StatementSource.FromAuthor(Disp(Statement2())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Expand signedSquare as sigma(r) times the original algebra square of e. Scalar associativity and sigma_sq cancel the two signs. IsSelfAdjoint.sq_nonneg then gives positivity of e squared in the original ordered C*-algebra."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement3"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.signedSquare_norm"),
            H("signedSquare_norm"), StatementSource.FromAuthor(Disp(Statement3())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("norm_smul and sigma_abs remove the sign without changing the norm. norm_pow_le bounds the original square norm by norm(e) squared. Since both norm(e) and L are nonnegative and norm(e) is at most L, squaring preserves this bound and gives L squared."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement4"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.selfAdjoint_lift"),
            H("selfAdjoint_lift"), StatementSource.FromAuthor(Disp(Statement4())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Choose any original preimage a of b from membership in pi.range, and replace it by its real symmetrization one half times (a+star a). map_add and map_star show that its image is one half times (b+star b), which equals b by self-adjointness. The construction needs no faithful or injective representation."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement5"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.bounded_strong_lift"),
            H("bounded_strong_lift"), StatementSource.FromAuthor(Disp(Statement5())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Set R=1+norm(T) before choosing vectors or accuracy and normalize B=T/R to a self-adjoint contraction. Its inverse Kaplansky value U satisfies f(U)=B by cfc_kaplanskyFun_cfc_kaplanskyFunInv. Irreducibility and closure_image_toPointwiseConvergenceCLM_inter_selfAdjoint, together with selfAdjoint_lift, put U in the strong closure of represented original self-adjoint elements. Along the resulting nontrivial neighborhood filter, tendsto_cfc_kaplanskyFun_apply and StarAlgHom.map_cfc make e=R cfc(f,a) approximate T strongly, while norm_cfc_kaplanskyFun_le bounds norm(e) in A by R. Intersecting the two eventual accuracy sets gives simultaneous approximation of x and y."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement6"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.square_reading"),
            H("square_reading"), StatementSource.FromAuthor(Disp(Statement6())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Self-adjointness of d makes pi(d) equal to its adjoint. apply_norm_sq_eq_inner_adjoint_right and multiplicativity express norm(pi(d)Omega) squared as the real part of the moment of d squared. The hypothesis hm identifies that moment with beta(square d), and Real.sqrt_sq removes the square using nonnegativity of the norm."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement7"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.signed_endpoint"),
            H("signed_endpoint"), StatementSource.FromAuthor(Disp(Statement7())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Write r=beta(k) and v=pi(k)Omega. Self-adjoint symmetry and hm give inner(v,Omega)=r. The positive rank-one operator S=abs(r) inverse times rankOne(v,v) therefore sends Omega to sigma(r)v, since r is nonzero and r/abs(r)=sigma(r). CFC.sqrt_nonneg makes T=sqrt(S) self-adjoint, and CFC.sqrt_mul_sqrt_self gives the required action of T squared. Both signs of r are handled explicitly."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement8"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/UniformSignedSquare.uniform_signed_original_square"),
            H("uniform_signed_original_square"), StatementSource.FromAuthor(Disp(Statement8())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("actual_pure_gns supplies the same-universe irreducible representation and exact original moments. Obtain T from signed_endpoint, then choose the bound L from bounded_strong_lift before any eta. Given eta>0, approximate T simultaneously on Omega and T(Omega) to delta=eta/(L+1); contractivity of pi bounds E=pi(e) by L, so the square error is less than L delta+delta=eta. square_reading converts this vector error into the original beta square reading; sigma_sq and sigma_abs preserve the sign and norm, while signedSquare_cone and signedSquare_norm provide the remaining original-algebra conclusions."))), DescribeRole.Theorem))));

